import json
from itertools import permutations

def build_adjacency(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    return adj

def compute_day_ranges(order, stays):
    # Overlapping transitions: next city starts on the same day the previous city ends
    day_ranges = {}
    current_start = 1
    for i, city in enumerate(order):
        if i == 0:
            start = 1
        else:
            start = prev_end  # overlap on transition day
        end = start + stays[city] - 1
        day_ranges[city] = (start, end)
        prev_end = end
    return day_ranges

def overlaps(a_start, a_end, b_start, b_end):
    return max(0, min(a_end, b_end) - max(a_start, b_start) + 1)

def valid_order(order, adj, stays, total_days, windows):
    # Check direct flights between consecutive cities
    for i in range(len(order)-1):
        if order[i+1] not in adj.get(order[i], set()):
            return False, None

    day_ranges = compute_day_ranges(order, stays)
    # Check total calendar length
    first_start = day_ranges[order[0]][0]
    last_end = day_ranges[order[-1]][1]
    if last_end - first_start + 1 != total_days:
        return False, None

    # Check city durations match exactly (they do by construction, but assert)
    for city, (s, e) in day_ranges.items():
        if e - s + 1 != stays[city]:
            return False, None

    # Check windows
    for w in windows:
        city = w["city"]
        s, e = day_ranges[city]
        if w["type"] == "must_cover":
            # city must include the entire window
            if not (s <= w["start"] and e >= w["end"]):
                return False, None
        elif w["type"] == "must_overlap":
            if overlaps(s, e, w["start"], w["end"]) <= 0:
                return False, None

    return True, day_ranges

def select_best_itinerary(cities, stays, total_days, edges, windows):
    adj = build_adjacency(edges)
    # Oslo must cover days 16-18; with our overlap model and fixed total days,
    # putting Oslo last guarantees it covers 16-18 exactly (since it has 3 days).
    last_city = "Oslo"
    others = [c for c in cities if c != last_city]

    best = None
    best_score = (-1, )  # tuple for lexicographic comparison
    best_day_ranges = None
    best_order = None

    for perm in permutations(others):
        order = list(perm) + [last_city]
        valid, day_ranges = valid_order(order, adj, stays, total_days, windows)
        if not valid:
            continue

        # Score: maximize Dubrovnik overlap with [5,9], then prefer Dubrovnik exactly within [5,9],
        # then prefer earlier Dubrovnik start.
        d_s, d_e = day_ranges["Dubrovnik"]
        overlap_count = overlaps(d_s, d_e, 5, 9)
        exact_within = int(d_s >= 5 and d_e <= 9)  # 1 if fully within
        # Prefer more overlap, then fully within, then Dubrovnik starting earlier (negative for min), then lex order
        score = (overlap_count, exact_within, -d_s)
        if score > best_score:
            best_score = score
            best = order
            best_day_ranges = day_ranges
            best_order = order

    return best_order, best_day_ranges

def main():
    # Input variables
    total_days = 18
    stays = {
        "Krakow": 5,
        "Frankfurt": 4,
        "Oslo": 3,
        "Dubrovnik": 5,
        "Naples": 5,
    }
    cities = list(stays.keys())

    # Direct flights (undirected pairs)
    edges = [
        ("Dubrovnik", "Oslo"),
        ("Frankfurt", "Krakow"),
        ("Frankfurt", "Oslo"),
        ("Dubrovnik", "Frankfurt"),
        ("Krakow", "Oslo"),
        ("Naples", "Oslo"),
        ("Naples", "Dubrovnik"),
        ("Naples", "Frankfurt"),
    ]

    # Windows: Oslo must cover days 16-18; Dubrovnik must overlap days 5-9
    windows = [
        {"city": "Oslo", "start": 16, "end": 18, "type": "must_cover"},
        {"city": "Dubrovnik", "start": 5, "end": 9, "type": "must_overlap"},
    ]

    order, day_ranges = select_best_itinerary(cities, stays, total_days, edges, windows)

    if not order or not day_ranges:
        # Fallback: no valid itinerary found
        output = {"itinerary": []}
    else:
        itinerary = []
        for city in order:
            s, e = day_ranges[city]
            itinerary.append({"day_range": f"Day {s}-{e}", "place": city})
        output = {"itinerary": itinerary}

    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
